# Batch 05 — Chapter V (Articles 44–50).
def rt(u, origin, cp, rtype, obj, fn, mod, cond="", note="", deriv="direct", unres="", flag="", acc="", ext_dep="", dep=""):
    return qr(u, origin, cp, rtype, obj, fn, mod, cond=cond, deriv=deriv, type_note=note, unresolved=unres, flag=flag, acc=acc, ext=ext_dep, dep=dep)
CTRL, PROC, DS, SA, COMMN = "controller", "processor", "data subject", "supervisory authority", "European Commission"
THIRD = pd("third country, territory or sector; international organisation (transfer destinations)", "position_type", "A45.P1", note="Categories of destinations; their own authorities (Art.45(2)(b)) are third-country bodies outside W.")
BCR = "binding corporate rules"

n = na("A44.P0", CTRL + " and " + PROC, "transfer personal data to a third country or international organisation only if the Chapter V conditions are complied with, including for onward transfers", "transfers", "implementation", "obligation", cp_status="none")
screen("A44.P0", "Yes", "operative-assignment", na=[n], status="Extracted")
# Art 45
n = na("A45.P1", COMMN, "decide that a third country, territory, sector or international organisation ensures an adequate level of protection (enabling transfers without specific authorisation)", "adequacy decision", "authorization/designation (adequacy)", "competence", cond="Commission decision; transfer then requires no specific authorisation", cp_status="none", dep="adequacy decision (device-like act)", note="The adequacy decision is an act of the Commission, not an institutional device; INS-TYPE.")
screen("A45.P1", "Yes", "operative-assignment (competence)", na=[n], pos=[THIRD], status="Extracted", note="Transfer permitted where a Commission decision exists; no SA authorisation needed.")
n = na("A45.P2", COMMN, "take account of listed elements (rule of law, independent supervisory authorities in the third country, international commitments) when assessing adequacy", "adequacy assessment", "monitoring/assessment", "obligation", cp_status="none", note="Point (b) refers to independent supervisory authorities of the third country and cooperation with Member States' SAs (position outside W).")
screen("A45.P2", "Yes", "operative-assignment", na=[n], status="Extracted")
n = na("A45.P3", COMMN, "adopt an adequacy decision by implementing act with a periodic review mechanism (at least every four years), specifying territorial/sectoral application and identifying the third-country supervisory authority", "adequacy implementing act", "rule-making (implementing)", "competence", cond="examination procedure of Art.93(2); after assessment", dep="Art.93(2) examination procedure", cp_status="none")
screen("A45.P3", "Yes", "operative-assignment (competence)", na=[n], status="Extracted")
n = na("A45.P4", COMMN, "monitor on an ongoing basis developments in third countries and international organisations that could affect adequacy decisions (including decisions under Art.25(6) of Directive 95/46/EC)", "monitoring of adequacy decisions", "monitoring", "obligation", cp_status="none")
screen("A45.P4", "Yes", "operative-assignment", na=[n], status="Extracted")
n = na("A45.P5", COMMN, "repeal, amend or suspend an adequacy decision where information reveals that adequacy is no longer ensured; immediately applicable implementing acts on imperative grounds of urgency (Art.93(3))", "repeal/amendment/suspension of adequacy decisions", "enforcement/rule-making (implementing)", "obligation", cond="available information, esp. following the review; examination procedure Art.93(2); urgency: Art.93(3)", dep="Art.93(2),(3)", cp_status="none")
screen("A45.P5", "Yes", "operative-assignment", na=[n], status="Extracted")
q = [rt("A45.P6", COMMN, "third country or international organisation", "representation/participation", "consultations with a view to remedying the situation giving rise to the decision under 45(5)", "cooperation/coordination", "obligation", cond="decision pursuant to paragraph 5", note="counterpart outside W")]
screen("A45.P6", "Yes", "relation-bearing", qr=q, status="Extracted")
screen("A45.P7", "No", "limitation", status="Not applicable", note="45(5) decision is without prejudice to transfers under Arts 46–49.")
n = na("A45.P8", COMMN, "publish in the Official Journal and on its website the list of countries, territories, sectors and international organisations for which adequacy is or is no longer ensured", "list of adequacy decisions", "information provision", "obligation", cp_status="none")
screen("A45.P8", "Yes", "operative-assignment", na=[n], status="Extracted")
screen("A45.P9", "No", "transitional-provision", status="Not applicable", note="Decisions under Art.25(6) of Directive 95/46/EC remain in force until replaced.")
ext("A45.P4;A45.P9", "Directive 95/46/EC (Art.25(6) decisions)", "legal_instrument", "transitional continuity of earlier adequacy decisions", "specifies", "Earlier decisions continue in force; their content is outside W.")
# Art 46
n = na("A46.P1", CTRL + " and " + PROC, "transfer personal data to a third country only if appropriate safeguards have been provided and enforceable data subject rights and effective legal remedies are available", "transfers subject to safeguards", "implementation", "obligation", cond="absence of an adequacy decision under 45(3)", cp_status="none")
screen("A46.P1", "Yes", "operative-assignment", na=[n], status="Extracted")
n = na("A46.P2", CTRL + " and " + PROC, "provide appropriate safeguards without specific SA authorisation by: (a) instrument between public authorities; (b) binding corporate rules (Art.47); (c) standard data protection clauses adopted by the Commission (Art.93(2)); (d) standard clauses adopted by a SA and approved by the Commission (Art.93(2)); (e) approved code of conduct (Art.40) with commitments; (f) approved certification mechanism (Art.42) with commitments", "safeguards for transfers", "implementation", "permission", cond="no specific authorisation from a supervisory authority required", dep="binding corporate rules (Art.47); standard data protection clauses; approved code of conduct (Art.40); approved certification mechanism (Art.42)", note="Links Chapter V to the instruments of Chapter IV Section 5 and to Art.47.", cp_status="none")
screen("A46.P2", "Yes", "operative-assignment; device-referencing", na=[n], status="Extracted", note="Six alternative routes; (e),(f) link to Arts 40, 42; (d) requires Commission approval of an SA-adopted instrument.")
q = [rt("A46.P3", SA + " (competent)", CTRL + " / " + PROC, "delegation/authorization", "authorisation of safeguards by (a) contractual clauses or (b) provisions in administrative arrangements between public authorities", "authorization", "competence", cond="appropriate safeguards provided by those means; subject to authorisation from the competent SA", note="gov-direction: SA authorises controller/processor's transfer safeguards")]
screen("A46.P3", "Yes", "relation-bearing", qr=q, status="Extracted")
n = na("A46.P4", SA, "apply the consistency mechanism (Art.63) in the cases referred to in 46(3)", "authorisation of transfer safeguards", "cooperation/coordination (procedural)", "obligation", dep="consistency mechanism (Art.63)", cp_status="none")
screen("A46.P4", "Yes", "operative-assignment; procedural-dependency", na=[n], status="Extracted", note="Procedural dependency: SA authorisations of contractual clauses go through Art.63.")
screen("A46.P5", "No", "transitional-provision", status="Not applicable", note="Authorisations and Commission decisions under Directive 95/46/EC remain valid.")
ext("A46.P5", "Directive 95/46/EC (Art.26(2),(4) authorisations and decisions)", "legal_instrument", "transitional continuity", "specifies", "Content outside W.")
# Art 47 BCR
q = [rt("A47.P1", SA + " (competent)", "group of undertakings (applicant)", "delegation/authorization", "approval of binding corporate rules in accordance with the consistency mechanism (Art.63), provided they are legally binding and enforced by every member, expressly confer enforceable rights on data subjects, and fulfil the requirements of 47(2)", "authorization (approval)", "obligation", cond="conditions (a)-(c)", note="gov-direction: SA approves BCR", dep="consistency mechanism (Art.63)")]
screen("A47.P1", "Yes", "relation-bearing; procedural-dependency", qr=q, status="Extracted", note="BCR approval: SA approval via Art.63 (device-like scheme: DEV threshold assessed in the register).")
n = na("A47.P2", "binding corporate rules (content requirement; addressees: groups of undertakings)", "specify at least points (a)-(n): group structure; transfers; binding nature; principles; data-subject rights; liability; information; DPO/monitoring tasks; complaint procedures; verification mechanisms (audits) with results communicated to the monitoring person, the board of the controlling undertaking and available on request to the SA; reporting of changes to the SA; cooperation with the SA; reporting of third-country legal requirements; training", "content of BCR", "rule-making (private/group)", "obligation", cp_status="none", note="Contains internal oversight and reporting relations (j),(k),(l),(m) toward the competent SA — recorded as content requirements; no relation is asserted among actual group members.", flag="subject-unstated")
q = [rt("A47.P2", "group of undertakings (BCR)", SA + " (competent)", "information/reporting", "mechanisms for reporting/recording changes to the rules and reporting those changes to the SA (k); cooperation mechanism incl. making verification results available (l); reporting of third-country legal requirements likely to have a substantial adverse effect (m); verification results available on request (j)", "information provision/cooperation", "obligation", cond="BCR content requirement (must be provided for in the rules)", note="content requirements on the BCR, not direct duties of the group; derived", deriv="derived", unres="relation exists only if the BCR contain the mechanisms; here recorded as a required content")]
screen("A47.P2", "Yes", "operative-assignment; relation-bearing (derived)", na=[n], qr=q, status="Extracted", note="Fourteen content points inventoried; (h),(j) internal monitoring and verification; (k),(l),(m) reporting to the SA.")
n = na("A47.P3", COMMN, "specify the format and procedures for the exchange of information between controllers, processors and supervisory authorities for BCR", "format and procedures for BCR information exchange", "rule-making (implementing)", "competence", cond="examination procedure of Art.93(2)", dep="Art.93(2) examination procedure", cp_status="none")
screen("A47.P3", "Yes", "operative-assignment (competence)", na=[n], status="Extracted")
screen("A48.P0", "No", "substantive-conduct-rule", status="Not applicable", note="Third-country judgments/decisions requiring transfer may only be recognised or enforceable if based on an international agreement; passive. Refers to international agreements (external).")
ext("A48.P0", "international agreements (e.g. mutual legal assistance treaties) in force between the third country and the Union or a Member State", "other_normative", "condition for recognition/enforceability", "conditions", "Content not retrieved; not part of W.")
# Art 49
n = na("A49.P1", CTRL, "transfer data in the absence of adequacy or appropriate safeguards only on conditions (a)-(g) or, as a last resort, where the transfer is not repetitive, concerns a limited number of data subjects, is necessary for compelling legitimate interests and suitable safeguards are provided after the controller's assessment", "derogations for transfers", "implementation", "obligation (conditions)", cond="absence of Art.45(3) decision and of Art.46 safeguards; conditions (a)-(g)", cp_status="none", note="Conditions of lawfulness; point (g) refers to registers 'which according to Union or Member State law' are intended to provide information to the public (registers not constituted here).")
q = [rt("A49.P1", CTRL, SA, "information/reporting", "information to the SA about a transfer based on compelling legitimate interests", "information provision", "obligation", cond="last-resort derogation (second subparagraph)"),
     rt("A49.P1", CTRL, DS, "information/reporting", "information to the data subject of the transfer and of the compelling legitimate interests pursued, in addition to Arts 13–14", "information provision", "obligation", cond="last-resort derogation")]
screen("A49.P1", "Yes", "operative-assignment; relation-bearing", na=[n], qr=q, status="Extracted")
screen("A49.P2", "No", "limitation", status="Not applicable", note="Limits on transfers from public registers.")
screen("A49.P3", "No", "exception", status="Not applicable", note="Disapplies certain derogations for public authorities in the exercise of public powers.")
screen("A49.P4", "No", "substantive-conduct-rule", status="Not applicable", note="Public interest to be recognised in Union or Member State law (legislator unnamed).")
n = na("A49.P5", "Union or Member State law (legislator not named)", "expressly set limits to the transfer of specific categories of personal data to a third country or international organisation, for important reasons of public interest", "limits on transfers", "rule-making (restriction)", "competence", cond="absence of an adequacy decision", cp_status="none", flag="subject-unstated")
q = [rt("A49.P5", "Member States", COMMN, "information/reporting", "notification of such provisions to the Commission", "information provision", "obligation", cond="Member State provisions limiting transfers under 49(5)")]
screen("A49.P5", "Yes", "operative-assignment (competence); relation-bearing", na=[n], qr=q, status="Extracted")
n = na("A49.P6", CTRL + " and " + PROC, "document the assessment and the suitable safeguards in the records referred to in Art.30", "documentation of derogation assessment", "information provision (internal record)", "obligation", dep="records of processing activities (Art.30)", cp_status="none")
screen("A49.P6", "Yes", "operative-assignment", na=[n], status="Extracted")
# Art 50
q = [rt("A50.P0", COMMN + " and " + SA + "s", "third countries and international organisations", "representation/participation", "international cooperation: (a) mechanisms for effective enforcement; (b) mutual assistance (notification, complaint referral, investigative assistance, information exchange); (c) engagement of stakeholders; (d) exchange and documentation of legislation and practice", "cooperation/coordination", "obligation", cond="appropriate steps; subject to appropriate safeguards (b)", note="counterpart categories outside W; four tasks (a)-(d) inventoried; promotional obligation ('take appropriate steps')")]
screen("A50.P0", "Yes", "relation-bearing", qr=q, status="Extracted", note="Common task of Commission and supervisory authorities toward third countries/international organisations.")
